<?php $g=get_option('andre_premium_geral',[]); $mid=function_exists('andre_media_option')?andre_media_option('hero_imagem'):0; ?>
<section class="hero"><div class="container hero-grid"><div><h1><?php echo esc_html($g['nome']??'Deputado Estadual André do Premium'); ?></h1><p><?php echo esc_html($g['subtitulo']??'Trabalho, compromisso regional e atuação parlamentar voltada ao desenvolvimento dos municípios goianos.'); ?></p><p><?php echo esc_html($g['hero_texto']??''); ?></p><div class="hero-btns"><?php if(!empty($g['btn1_txt'])) echo '<a class="btn" href="'.esc_url($g['btn1_url']??'#').'">'.esc_html($g['btn1_txt']).'</a>'; if(!empty($g['btn2_txt'])) echo '<a class="btn btn-alt" href="'.esc_url($g['btn2_url']??'#').'">'.esc_html($g['btn2_txt']).'</a>'; ?></div></div><div><?php if($mid){ echo wp_get_attachment_image($mid,'large',false,['loading'=>'lazy']); } elseif(!empty($g['hero_img'])) echo wp_get_attachment_image((int)$g['hero_img'],'large',false,['loading'=>'lazy']); ?></div></div></section>
